SourceCode.Declaration:
public class TFMSearchTypeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TFMOrderTypes   orderType;
}

Method.Source:
///<summary>
/// Returns the key used for storing cached data for this attribute.
/// </summary>
/// <returns>
/// A string representing the cache key.
/// </returns>
public str parmCacheKey()
{
    return classStr(TFMSearchTypeAttribute)+';'+orderType;
}

public TFMOrderTypes parmType(TFMOrderTypes _type = orderType)
{
    orderType = _type;

    return orderType;
}

///<summary>
/// Determines if the same instance should be returned by the extension framework.
/// </summary>
/// <returns>
/// true if the same instance should be returned; otherwise false.
/// </returns>
public boolean useSingleton()
{
    return false;
}
